def copy_foto_to_photos(apps, schema_editor):
    Vehicle = apps.get_model("fleet", "Vehicle")
    VehiclePhoto = apps.get_model("fleet", "VehiclePhoto")
    for vehicle in Vehicle.objects.exclude(foto=""):
        VehiclePhoto.objects.create(vehicle=vehicle, image=vehicle.foto.name)


def copy_first_photo_back(apps, schema_editor):
    Vehicle = apps.get_model("fleet", "Vehicle")
    VehiclePhoto = apps.get_model("fleet", "VehiclePhoto")
    for vehicle in Vehicle.objects.all():
        first = VehiclePhoto.objects.filter(vehicle=vehicle).order_by("id").first()
        if first:
            vehicle.foto = first.image.name
            vehicle.save(update_fields=["foto"])


